import logging
import random

from ute_ue.config.loggers import LoggerAdapter4EmptyExtra

from taf.ue.iphone.exceptions import NoFreePortException

DEFAULT_PORT_MIN = 50000
DEFAULT_PORT_MAX = 60000
DEFAULT_PORT_SEARCH_ATTEMPTS = 100


class FreeTcpPortFinder:
    """Used to find free port to be used by iperf"""

    _logger = LoggerAdapter4EmptyExtra(logging.getLogger('ute_ue.ue'), {'layer': 'DATATRANSFER'})

    @staticmethod   # noqa
    def is_port_free_in_netstat(netstat_output, port):  # noqa
        if isinstance(netstat_output, list):
            if all(isinstance(element, dict) for element in netstat_output):
                for connection in netstat_output:
                    local_address = connection.get("local address", '')
                    if local_address and f':{port}' in local_address :
                        return False
            elif all(isinstance(element, str) for element in netstat_output):
                return all(f':{port}' and f".{port}" not in line for line in netstat_output)
        elif isinstance(netstat_output, str):
            netstat_output = netstat_output.split('\n')
            return all(f':{port}' and f".{port}" not in line for line in netstat_output)
        return True

    @staticmethod
    def find_random_free_port(min_port: int, max_port: int, attempts: int, port_validator=lambda port: True) -> int:
        """Searches free tcp port.
        :param port_validator: Port validation function, returns boolean which indicates if port is free
        :param min_port: Minimal port value to search
        :param max_port: Maximal port value to search
        :param attempts: Number of tries to find free port before raise an exception
        """
        FreeTcpPortFinder._logger.debug(f"Starting free port search in range {min_port}-{max_port}.")
        for i in range(attempts):
            port = random.randint(min_port, max_port)
            is_port_free = port_validator(port)
            FreeTcpPortFinder._logger.debug(f"Search attempt {i}. Port {port} is "
                                            f"{'free' if is_port_free else 'already in use'}.")
            if is_port_free:
                return port
        raise NoFreePortException(f"No free port was found in {attempts} attempts")
